var minimumEffort = function(tasks) {
    let total = 0;
    let curr = 0;

    tasks.sort((a, b) => {
        const diffA = Math.abs(a[0] - a[1]);
        const diffB = Math.abs(b[0] - b[1]);

        return diffA === diffB ? b[1] - a[1] : diffB - diffA;
    });

    for (const [actual, minimum] of tasks) {
        const diff = Math.max(0, minimum - curr);

        total += diff;
        curr += diff - actual;
    }

    return total;
};

